import {
  autoUpdate,
  flip,
  offset,
  safePolygon,
  shift,
  useFloating,
  useFocus,
  useHover,
  useInteractions,
  useRole,
} from "@floating-ui/react";
import { type TeamHuntState } from "@hunt/public-client";
import {
  GlitchEffect,
  type ResolvedCutsceneContent,
  CutsceneDisplay,
} from "@hunt/puzzle-components";
import {
  Button,
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@hunt/shadcn";
import React, { useEffect, useState, type CSSProperties } from "react";
import { usePuzzleState } from "../../../components/PuzzleAndTaskDisplay/PuzzleCard";
import {
  TeamStateProvider,
  useTeamState,
} from "../../../components/TeamStateProvider";
import { PuzzleTooltipComponent } from "../../../components/Tooltip";
import OverworldPuzzleList from "../../../components/overworld/PuzzleList";
import { HubFonts } from "../../../hub/HubFonts";
import WaterBackground from "../../../hub/assets/misc/water_bg_transparent.png";
import MapBackground from "../../../hub/assets/zones/Background.png";
import { ZONE_BASE_POSITION } from "../../../hub/index";
import { centerFloatingMiddleware } from "../../../utils/floating";
import type { GlitchState, GlitchPuzzleDisplay } from "./types";

const OVERWORLD_IMAGE_WIDTH = 960;
const PUZZLE_LIST_TOP_MARGIN = 800;
const PHOTOSENSITIVITY_WARNING_STORAGE_KEY =
  "glitch_photosensitivity_warning_acknowledged";

type EntityContainerProps = {
  clickable?: boolean;
  style?: CSSProperties;
  children: React.ReactNode;
  href?: string;
  className?: string;
  referenceProps?: Record<string, unknown>;
  referenceRef?: React.Ref<HTMLAnchorElement>;
};

const EntityContainer = ({
  clickable,
  style,
  children,
  href,
  className = "",
  referenceProps,
  referenceRef,
}: EntityContainerProps) => {
  const baseClasses = "block p-0 border-0 bg-transparent absolute";
  const clickableClass = clickable ? "cursor-pointer" : "";
  const classes = `${baseClasses} ${clickableClass} ${className}`;
  const [isClient, setIsClient] = useState(false);
  useEffect(() => {
    setIsClient(true);
  }, []);
  if (href) {
    return isClient ? (
      <a
        style={style}
        href={href}
        className={classes}
        ref={referenceRef}
        {...referenceProps}
      >
        <GlitchEffect size="small">{children}</GlitchEffect>
      </a>
    ) : (
      <a style={style} href={href} className={classes}>
        {children}
      </a>
    );
  }
  return (
    <button
      type="button"
      style={style}
      className={`${baseClasses} ${className} cursor-default`}
    >
      {children}
    </button>
  );
};

const GlitchMapPuzzleEntity = ({
  puzzleDisplay,
  tooltipChildren,
}: {
  puzzleDisplay: GlitchPuzzleDisplay & {
    puzzle: NonNullable<GlitchPuzzleDisplay["puzzle"]>;
  };
  tooltipChildren?: React.ReactNode;
}) => {
  const { epoch } = useTeamState();
  const [showTooltip, setShowTooltip] = useState(false);

  // Hooks are now at the top level of this component
  const puzzleStateHandle = usePuzzleState(epoch, puzzleDisplay.puzzle);
  const puzzleState = puzzleStateHandle[0];

  const tooltipPosition = puzzleDisplay.tooltip_position ?? "center";
  const isCenterTooltip = tooltipPosition === "center";

  const { refs, floatingStyles, context } = useFloating({
    placement: isCenterTooltip ? "top" : tooltipPosition,
    open: showTooltip,
    onOpenChange: setShowTooltip,
    middleware: isCenterTooltip
      ? [centerFloatingMiddleware, shift()]
      : [offset(5), flip(), shift()],
    whileElementsMounted: autoUpdate,
  });

  const hover = useHover(context, { move: false, handleClose: safePolygon() });
  const focus = useFocus(context);
  const role = useRole(context, { role: "label" });
  const { getReferenceProps, getFloatingProps } = useInteractions([
    hover,
    focus,
    role,
  ]);

  const dynamicContainerStyle = {
    top: puzzleDisplay.pos.top,
    left: puzzleDisplay.pos.left,
    zIndex: puzzleDisplay.z_index ?? 10,
  };

  const image = (
    <img
      src={puzzleDisplay.asset}
      alt={puzzleDisplay.puzzle.title}
      className="w-full select-none pointer-events-auto cursor-pointer"
    />
  );

  const tooltip = showTooltip && (
    <PuzzleTooltipComponent
      innerRef={refs.setFloating}
      style={{ ...floatingStyles, visibility: "visible", zIndex: 100 }}
      title={puzzleState.title}
      answer={puzzleState.answer}
      desc={puzzleState.desc}
      lockState={puzzleState.state}
      nsfw={puzzleDisplay.puzzle.nsfw}
      {...getFloatingProps()}
    >
      {tooltipChildren}
    </PuzzleTooltipComponent>
  );

  return (
    <>
      <EntityContainer
        style={dynamicContainerStyle}
        href={`/puzzles/${puzzleState.slug}`}
        referenceRef={refs.setReference}
        referenceProps={getReferenceProps()}
      >
        {image}
      </EntityContainer>
      {tooltip}
    </>
  );
};

const GlitchMapEntity = ({
  puzzleDisplay,
  tooltipChildren,
}: {
  puzzleDisplay: GlitchPuzzleDisplay;
  tooltipChildren?: React.ReactNode;
}) => {
  // This component now only decides which component to render.
  // It no longer calls any hooks conditionally.
  if (puzzleDisplay.puzzle === undefined) {
    const dynamicContainerStyle = {
      top: puzzleDisplay.pos.top,
      left: puzzleDisplay.pos.left,
    };
    const image = (
      <img src={puzzleDisplay.asset} alt="" className="w-full select-none" />
    );
    return (
      <EntityContainer style={dynamicContainerStyle}>{image}</EntityContainer>
    );
  }

  return (
    <GlitchMapPuzzleEntity
      puzzleDisplay={
        puzzleDisplay as GlitchPuzzleDisplay & {
          puzzle: NonNullable<GlitchPuzzleDisplay["puzzle"]>;
        }
      }
      tooltipChildren={tooltipChildren}
    />
  );
};

type PhotosensitivityWarningModalProps = {
  isOpen: boolean;
  onAcknowledge: () => void;
};

function PhotosensitivityWarningModal({
  isOpen,
  onAcknowledge,
}: PhotosensitivityWarningModalProps) {
  return (
    <Dialog
      open={isOpen}
      onOpenChange={() => {
        // Prevent closing by clicking outside or pressing escape
      }}
    >
      <DialogContent
        onPointerDownOutside={(e) => {
          e.preventDefault();
        }}
        onEscapeKeyDown={(e) => {
          e.preventDefault();
        }}
        className="fixed left-1/2 top-1/2 z-[102] w-[90vw] max-w-xl -translate-x-1/2 -translate-y-1/2 rounded-lg border border-gray-200 bg-white p-6 text-black shadow-2xl"
      >
        <DialogHeader>
          <DialogTitle className="text-lg font-semibold text-black">
            Photosensitivity Warning
          </DialogTitle>
          <DialogDescription className="text-sm font-semibold">
            This round page contains visual effects that may cause discomfort
            for viewers who are sensitive to flashing lights or patterns.
          </DialogDescription>
        </DialogHeader>
        <div className="text-sm text-gray-700 space-y-2 py-4">
          <p>
            If that represents an issue, we recommend you access the puzzles in
            this round from the{" "}
            <a href="/puzzles" className="underline text-blue-600">
              All Puzzles page.
            </a>
          </p>
          <p>
            The puzzles themselves also contain significantly smaller visual
            effects that we expect do not represent a significant
            photosensitivity risk, but we mention here out of an abundance of
            caution.
          </p>
        </div>
        <DialogFooter className="gap-2 justify-end sm:flex-row items-center">
          <Button
            variant="default"
            onClick={onAcknowledge}
            className="bg-blue-900 text-white hover:bg-blue-800"
          >
            I understand, continue
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

const GlitchBody = ({
  state,
  teamState,
  cutsceneContent,
}: {
  state: GlitchState;
  teamState: TeamHuntState;
  cutsceneContent?: ResolvedCutsceneContent[];
}) => {
  const [showWarning, setShowWarning] = useState(false);

  useEffect(() => {
    // Check if user has already acknowledged the warning
    const acknowledged =
      localStorage.getItem(PHOTOSENSITIVITY_WARNING_STORAGE_KEY) === "true";
    if (!acknowledged) {
      setShowWarning(true);
    }
  }, []);

  const handleAcknowledge = () => {
    localStorage.setItem(PHOTOSENSITIVITY_WARNING_STORAGE_KEY, "true");
    setShowWarning(false);
  };

  const hasPuzzle = (
    puzzleDisplay: GlitchPuzzleDisplay,
  ): puzzleDisplay is GlitchPuzzleDisplay & {
    puzzle: NonNullable<GlitchPuzzleDisplay["puzzle"]>;
  } => puzzleDisplay.puzzle !== undefined;

  const puzzles = state.puzzles
    .filter(hasPuzzle)
    .map((puzzle) => puzzle.puzzle);
  const allFeedersDiscovered = state.puzzles.every(hasPuzzle);
  const roundSlug = "the_glitch";
  const roundName = teamState.rounds[roundSlug]?.title ?? "";

  return (
    <TeamStateProvider teamState={teamState}>
      <PhotosensitivityWarningModal
        isOpen={showWarning}
        onAcknowledge={handleAcknowledge}
      />
      {!showWarning && (
        <>
          <HubFonts />
          <div
            className={`min-w-[${OVERWORLD_IMAGE_WIDTH}px] min-h-screen flex flex-col items-center justify-start`}
            style={{
              backgroundColor: "#032b63",
              backgroundImage: `url(${WaterBackground})`,
              backgroundRepeat: "repeat",
              imageRendering: "pixelated",
            }}
          >
            {/* Map and puzzle images */}
            <div className="w-full flex justify-center">
              <div
                className={`w-full max-w-[${OVERWORLD_IMAGE_WIDTH}px] pt-12 flex flex-col items-center gap-12`}
              >
                <div
                  id="main-content"
                  className={`w-[${OVERWORLD_IMAGE_WIDTH}px] mx-auto`}
                >
                  <div
                    className="relative"
                    style={{
                      width: `${OVERWORLD_IMAGE_WIDTH}px`,
                      height: `${PUZZLE_LIST_TOP_MARGIN}px`,
                    }}
                  >
                    <img
                      src={MapBackground}
                      alt=""
                      aria-hidden="true"
                      className="pointer-events-none absolute select-none"
                      style={{
                        top: ZONE_BASE_POSITION.y,
                        left: ZONE_BASE_POSITION.x,
                        imageRendering: "pixelated",
                      }}
                    />
                    {state.puzzles.map((puzzle) => (
                      <GlitchMapEntity
                        key={
                          puzzle.puzzle?.slug ??
                          `${puzzle.pos.left}-${puzzle.pos.top}`
                        }
                        puzzleDisplay={puzzle}
                      />
                    ))}
                  </div>
                </div>
              </div>
            </div>
            {/* Puzzle list section below the map */}
            <div className="w-full flex justify-center pb-8">
              <OverworldPuzzleList
                puzzles={puzzles}
                allFeedersDiscovered={allFeedersDiscovered}
                roundName={roundName}
                roundSlug={roundSlug}
              />
            </div>
          </div>

          <CutsceneDisplay content={cutsceneContent} />
        </>
      )}
    </TeamStateProvider>
  );
};

export default GlitchBody;
