import React, { useMemo } from "react";
import {
  type AllPuzzlesRound,
  type AllPuzzlesState,
} from "../../client/all_puzzles_types";
import { type PuzzleSummary } from "../../rounds/types";
import { IS_STATIC_SITE } from "../../utils/staticSite";
import PuzzleCard from "../PuzzleAndTaskDisplay/PuzzleCard";
import { RoundFolder } from "../PuzzleAndTaskDisplay/RoundFolder";
import { type Style } from "../PuzzleAndTaskDisplay/useFolderHeights";
import {
  applySolvedMapToPuzzleSummaries,
  useSolvedPuzzlesState,
} from "../puzzleSolveLocalState";

const STATIC_FOLDER_STYLE: Style = {
  height: "auto",
  sticky: false,
  marginTop: 0,
};

const getStaticStyle = () => STATIC_FOLDER_STYLE;

export default function OverworldPuzzleList({
  puzzles,
  roundName,
  allFeedersDiscovered,
  roundSlug,
}: {
  puzzles: PuzzleSummary[];
  roundName: string;
  allFeedersDiscovered: boolean;
  roundSlug: string;
}) {
  const { solvedMap } = useSolvedPuzzlesState();
  const mergedPuzzles = useMemo(() => {
    if (!IS_STATIC_SITE) return puzzles;
    return applySolvedMapToPuzzleSummaries(puzzles, solvedMap);
  }, [puzzles, solvedMap]);
  const folderRound = useMemo<AllPuzzlesRound>(
    () => ({
      slug: roundSlug,
      title: "Puzzles",
      puzzles: mergedPuzzles.map((puzzle) => ({
        slug: puzzle.slug,
        title: puzzle.title,
        desc: puzzle.desc,
        state: puzzle.state,
        answer: puzzle.answer,
        unlock_cost: puzzle.unlock_cost,
        nsfw: puzzle.nsfw,
        physical_presence_requirement: puzzle.physical_presence_requirement,
        is_overworld_feeder: puzzle.is_overworld_feeder,
        is_meta: puzzle.is_meta,
        is_capstone: puzzle.is_capstone,
        round_slug: roundSlug,
      })),
      is_overworld_round: true,
    }),
    [mergedPuzzles, roundSlug],
  );

  const folderState = useMemo<AllPuzzlesState>(
    () => ({
      epoch: 0,
      rounds: [folderRound],
      currency: 0,
    }),
    [folderRound],
  );

  const wrapper = (children: React.ReactNode) => (
    <div className="w-full flex justify-center pb-8 mt-8">
      <div className="w-full max-w-screen-lg px-4">{children}</div>
    </div>
  );

  const puzzmonMessage = useMemo(() => {
    if (allFeedersDiscovered) {
      return `You've encountered every Puzzmon in ${roundName}!`;
    }
    if (mergedPuzzles.length === 0) {
      return `No puzzles found. Encounter Puzzmon in the wild by exploring ${roundName}!`;
    }
    return `Encounter more Puzzmon in the wild by exploring ${roundName}!`;
  }, [allFeedersDiscovered, mergedPuzzles.length, roundName]);

  const content = (
    <div className="w-full px-3 pb-3 flex flex-col gap-3">
      <div className="flex flex-col gap-3">
        {roundSlug !== "the_glitch" && (
          <p className="text-lg text-neutral-800 italic text-center w-full">
            {puzzmonMessage}
          </p>
        )}
        {mergedPuzzles.map((puzzle) => (
          <PuzzleCard
            key={puzzle.slug}
            lockState={puzzle.state}
            title={puzzle.title}
            slug={puzzle.slug}
            desc={puzzle.desc ?? ""}
            unlock_cost={puzzle.unlock_cost}
            is_overworld_feeder={puzzle.is_overworld_feeder}
            answer={puzzle.answer}
            nsfw={puzzle.nsfw}
            physicalPresenceRequirement={puzzle.physical_presence_requirement}
            meta={puzzle.is_meta}
            capstone={puzzle.is_capstone}
          />
        ))}
      </div>
    </div>
  );

  return wrapper(
    <RoundFolder
      variant="overworld"
      round={folderRound}
      count={mergedPuzzles.length}
      index={0}
      getStyle={getStaticStyle}
      state={folderState}
      href={`/rounds/${roundSlug}`}
    >
      {content}
    </RoundFolder>,
  );
}
