import { cn } from "@hunt/styled-ui";
import { TriangleAlert } from "lucide-react";
import React, { type CSSProperties } from "react";
import { type LockState, PuzzleIcon } from "./PuzzleAndTaskDisplay/PuzzleCard";

type TooltipProps = {
  title: string;
  answer?: string;
  desc?: string;
  lockState: LockState;
  children?: React.ReactNode;
  innerRef?: React.Ref<HTMLDivElement>;
  style?: CSSProperties;
  nsfw?: boolean;
  className?: string;
  iconOverride?: React.ReactNode;
};

export const PuzzleTooltipComponent = ({
  lockState,
  title,
  answer,
  desc,
  children,
  style = {},
  innerRef,
  nsfw,
  className,
  iconOverride,
}: TooltipProps) => {
  return (
    <div
      ref={innerRef}
      style={style}
      className={cn(
        "absolute z-50 text-sm font-medium leading-[1.25] text-black bg-white px-3 py-1.5 rounded-md shadow-lg flex flex-col items-center justify-center gap-1 max-w-[80vw] select-none cursor-default pointer-events-none",
        className,
      )}
    >
      {children}
      {nsfw && (
        <div className="flex items-center bg-red-50 px-2 py-1 rounded-md border border-red-200 mb-1">
          <TriangleAlert className="w-6 h-6 text-red-600" />
          <span className="ml-2 text-xs text-red-500">Mature content</span>
        </div>
      )}
      <span className="flex items-center gap-1 text-left">
        {iconOverride ?? <PuzzleIcon lockState={lockState} solved={!!answer} />}
        <span>{title}</span>
      </span>
      {!answer && desc && (
        <span className="text-gray-700 italic font-light">{desc}</span>
      )}
      {answer && (
        <span className="font-bold font-mono text-base text-green-600">
          {answer}
        </span>
      )}
    </div>
  );
};
