import { type TeamHuntState } from "@hunt/public-client";
import { type ResolvedCutsceneContent } from "@hunt/puzzle-components";
import React from "react";
import { hydrateRoot } from "react-dom/client";
import useDataset from "../../../client/useDataset";
import GlitchBody from "./GlitchBody";
import { type GlitchState } from "./types";

const GlitchManager = ({
  initialState,
  initialTeamState,
  cutsceneContent,
}: {
  initialState: GlitchState;
  initialTeamState: TeamHuntState;
  cutsceneContent: ResolvedCutsceneContent[];
}) => {
  const state = useDataset("the_glitch", undefined, initialState);
  const teamState = useDataset("team_state", undefined, initialTeamState);
  return (
    <GlitchBody
      state={state}
      teamState={teamState}
      cutsceneContent={cutsceneContent}
    />
  );
};

const elem = document.getElementById("glitch-root");
if (elem) {
  const state = (window as unknown as { initialGlitchState: GlitchState })
    .initialGlitchState;
  const teamState = (window as unknown as { initialTeamState: TeamHuntState })
    .initialTeamState;
  const cutsceneContent = (
    window as unknown as { initialCutsceneContent: ResolvedCutsceneContent[] }
  ).initialCutsceneContent;
  hydrateRoot(
    elem,
    <GlitchManager
      initialState={state}
      initialTeamState={teamState}
      cutsceneContent={cutsceneContent}
    />,
  );
} else {
  console.error(
    "Could not mount GlitchManager because #glitch-root was nowhere to be found",
  );
}
